<style>
.qb-design{--qb-bg:#f4f7fc;--qb-card:#fff;--qb-card-2:#f8faff;--qb-border:#d6e1f0;--qb-text:#142540;--qb-muted:#617798;--qb-blue:#1769ed;--qb-blue-soft:#e9f1ff;--qb-green:#087e55;--qb-green-soft:#e5f8ee;--qb-amber:#a76600;--qb-amber-soft:#fff4db;--qb-red:#c33d53;--qb-purple:#6555c9;color:var(--qb-text)}
.dark .qb-design{--qb-bg:#07152c;--qb-card:#0d203c;--qb-card-2:#0a1b34;--qb-border:#29476c;--qb-text:#f4f7ff;--qb-muted:#9eb7da;--qb-blue:#3988ff;--qb-blue-soft:#102e5c;--qb-green:#24d996;--qb-green-soft:#083a35;--qb-amber:#ffbc49;--qb-amber-soft:#4d310f;--qb-red:#fb5d75;--qb-purple:#8e82fb}
.qb-design.fi-page{background:var(--qb-bg);border-radius:16px;padding:24px;min-height:100vh;max-width:none!important}
.qb-design .fi-header{align-items:center;gap:20px;margin-bottom:24px}
.qb-design .fi-header-heading{font-size:clamp(2rem,3vw,3rem);font-weight:800;letter-spacing:-.03em;line-height:1.15;color:var(--qb-text)}
.qb-design .fi-header-subheading{font-size:1rem;color:var(--qb-muted);margin-top:8px}
.qb-design .fi-header-actions{gap:10px;flex-wrap:wrap}
.qb-design .fi-header-actions .fi-btn{min-height:44px;border-radius:10px;padding-inline:16px;box-shadow:none;font-weight:650}
.qb-design .fi-header-actions .fi-btn:not(.fi-color-primary){background:var(--qb-card);border:1px solid var(--qb-border);color:var(--qb-text)}
.qb-design .fi-header-actions .fi-btn.fi-color-primary{background:#216df3;color:white}
.qb-canvas{display:grid;gap:18px;direction:inherit}
.qb-card{background:linear-gradient(125deg,var(--qb-card),var(--qb-card-2));border:1px solid var(--qb-border);border-radius:14px;box-shadow:0 12px 32px rgba(0,7,25,.08);min-width:0}
.dark .qb-card{box-shadow:0 12px 32px rgba(0,0,0,.12)}
.qb-section{padding:20px}
.qb-section-head{display:flex;align-items:flex-start;gap:12px;margin-bottom:18px;min-width:0}
.qb-section-head h2{font-size:1.22rem;font-weight:750;line-height:1.35;margin:0;color:var(--qb-text)}
.qb-section-head p{font-size:.84rem;color:var(--qb-muted);margin:5px 0 0;line-height:1.5}
.qb-icon{width:40px;height:40px;flex:none;display:inline-flex;align-items:center;justify-content:center;border-radius:9px;color:var(--qb-blue);background:var(--qb-blue-soft);border:1px solid color-mix(in srgb,var(--qb-blue) 37%,transparent)}
.qb-icon svg{width:23px;height:23px}
.qb-icon--green{color:var(--qb-green);background:var(--qb-green-soft);border-color:color-mix(in srgb,var(--qb-green) 42%,transparent)}
.qb-icon--amber{color:var(--qb-amber);background:var(--qb-amber-soft);border-color:color-mix(in srgb,var(--qb-amber) 42%,transparent)}
.qb-icon--purple{color:var(--qb-purple);background:color-mix(in srgb,var(--qb-purple) 17%,var(--qb-card));border-color:color-mix(in srgb,var(--qb-purple) 44%,transparent)}
.qb-icon--muted{color:var(--qb-muted);background:var(--qb-card-2);border-color:var(--qb-border)}
.qb-pill{display:inline-flex;align-items:center;gap:5px;border:1px solid currentColor;border-radius:7px;padding:4px 9px;font-size:.76rem;font-weight:700;line-height:1.15;white-space:nowrap}
.qb-pill--green{color:var(--qb-green);background:var(--qb-green-soft)}
.qb-pill--amber{color:var(--qb-amber);background:var(--qb-amber-soft)}
.qb-pill--red{color:var(--qb-red);background:color-mix(in srgb,var(--qb-red) 13%,var(--qb-card))}
.qb-pill--gray{color:var(--qb-muted);background:var(--qb-card-2)}
