.qb-hero-art{grid-column:2;grid-row:1}.qb-hero-main{grid-column:1;grid-row:1}
.qb-hero--amber{border-color:color-mix(in srgb,var(--qb-amber) 70%,var(--qb-border));background:radial-gradient(circle at 9% 65%,color-mix(in srgb,var(--qb-amber) 24%,transparent),transparent 28%),linear-gradient(112deg,color-mix(in srgb,var(--qb-amber) 9%,var(--qb-card)),var(--qb-card-2) 70%)}
.qb-hero--green{border-color:color-mix(in srgb,var(--qb-green) 75%,var(--qb-border));background:radial-gradient(circle at 9% 60%,color-mix(in srgb,var(--qb-green) 23%,transparent),transparent 30%),linear-gradient(112deg,color-mix(in srgb,var(--qb-green) 9%,var(--qb-card)),var(--qb-card-2) 72%)}
.qb-hero-art{height:150px;display:flex;align-items:center;justify-content:center;position:relative;color:var(--qb-amber)}
.qb-hero-art:before,.qb-hero-art:after{content:"";position:absolute;inset:auto 10px 5px;border:1px solid currentColor;border-radius:50%;height:38px;opacity:.22}
.qb-hero-art:after{inset:auto 32px 14px;height:25px;opacity:.15}
.qb-hero-art svg{width:94px;height:94px;stroke-width:1.25;filter:drop-shadow(0 0 18px currentColor);z-index:1}
.qb-hero--green .qb-hero-art{color:var(--qb-green)}
.qb-hero-main{min-width:0}
.qb-hero-heading{display:flex;align-items:center;flex-wrap:wrap;gap:12px}
